import React from "react";
import { cx } from "@/lib/utils";

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: "gold" | "sage" | "rust" | "charcoal" | "outline";
  size?: "sm" | "md";
}

export const Badge: React.FC<BadgeProps> = ({
  children,
  className,
  variant = "gold",
  size = "md",
  ...props
}) => {
  const baseStyles =
    "inline-flex items-center gap-1.5 font-semibold uppercase tracking-wider rounded-full transition-colors";

  const variantStyles = {
    gold: "bg-brand-gold/15 text-brand-gold border border-brand-gold/30",
    sage: "bg-brand-sage/15 text-brand-sage border border-brand-sage/30",
    rust: "bg-brand-rust/15 text-brand-rust border border-brand-rust/30",
    charcoal: "bg-brand-charcoal text-white/80 border border-white/10",
    outline: "bg-transparent text-white/70 border border-white/20",
  };

  const sizeStyles = {
    sm: "text-[10px] px-2.5 py-0.5",
    md: "text-xs px-3 py-1",
  };

  return (
    <span
      className={cx(
        baseStyles,
        variantStyles[variant],
        sizeStyles[size],
        className
      )}
      {...props}
    >
      {children}
    </span>
  );
};

export default Badge;
