import React from "react";
import { cx } from "@/lib/utils";

export interface SectionHeadingProps
  extends React.HTMLAttributes<HTMLDivElement> {
  eyebrow?: string;
  title: string;
  subtitle?: string;
  align?: "left" | "center" | "right";
  withRule?: boolean;
}

export const SectionHeading: React.FC<SectionHeadingProps> = ({
  eyebrow,
  title,
  subtitle,
  align = "center",
  withRule = true,
  className,
  ...props
}) => {
  const alignmentStyles = {
    left: "text-left items-start",
    center: "text-center items-center",
    right: "text-right items-end",
  };

  const ruleAlignment = {
    left: "mr-auto",
    center: "mx-auto",
    right: "ml-auto",
  };

  return (
    <div
      className={cx("flex flex-col mb-12", alignmentStyles[align], className)}
      {...props}
    >
      {eyebrow && (
        <span className="mb-2 text-xs font-semibold uppercase tracking-widest text-brand-gold">
          {eyebrow}
        </span>
      )}
      <h2 className="font-display text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight text-white">
        {title}
      </h2>
      {withRule && (
        <div
          className={cx(
            "my-4 h-0.5 w-16 bg-gradient-to-r from-brand-gold to-transparent",
            ruleAlignment[align]
          )}
        />
      )}
      {subtitle && (
        <p className="max-w-2xl text-base sm:text-lg text-white/70">
          {subtitle}
        </p>
      )}
    </div>
  );
};

export default SectionHeading;
